import{_ as n,o as a,c as i,a2 as e}from"./chunks/framework.BgftbQsK.js";const u=JSON.parse('{"title":"Tmux — Terminal Multiplexer","description":"Why tmux for persistent sessions, complete cheatsheet (sessions, windows, panes, scrolling), and custom config with mouse support and Ctrl+A prefix.","frontmatter":{"title":"Tmux — Terminal Multiplexer","order":21,"description":"Why tmux for persistent sessions, complete cheatsheet (sessions, windows, panes, scrolling), and custom config with mouse support and Ctrl+A prefix.","head":[["meta",{"name":"og:title","content":"Tmux — Terminal Multiplexer | Ubuntu Home Lab Server"}],["meta",{"property":"og:description","content":"Why tmux for persistent sessions, complete cheatsheet (sessions, windows, panes, scrolling), and custom config with mouse support and Ctrl+A prefix."}]]},"headers":[],"relativePath":"chapters/21-tmux-terminal-multiplexer.md","filePath":"chapters/21-tmux-terminal-multiplexer.md","lastUpdated":null}'),p={name:"chapters/21-tmux-terminal-multiplexer.md"};function l(t,s,r,h,c,k){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h2 id="why-tmux" tabindex="-1">Why Tmux? <a class="header-anchor" href="#why-tmux" aria-label="Permalink to &quot;Why Tmux?&quot;">​</a></h2><p>When your SSH connection drops, every terminal process you had running dies. If you were running a 6-hour data cleaning job, it&#39;s gone.</p><p>Tmux runs a persistent terminal server on your server. Your sessions survive disconnects. You can detach and reattach from any device.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmux</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create a new session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Detach (session keeps running)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Ctrl+B,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> D</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List sessions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reattach</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attach</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or just</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # attach to most recent</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h2 id="tmux-cheatsheet" tabindex="-1">Tmux Cheatsheet <a class="header-anchor" href="#tmux-cheatsheet" aria-label="Permalink to &quot;Tmux Cheatsheet&quot;">​</a></h2><p>All tmux commands start with the <strong>prefix</strong>: <code>Ctrl+B</code></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Sessions</span></span>
<span class="line"><span>Ctrl+B, D           Detach from session</span></span>
<span class="line"><span>Ctrl+B, $           Rename session</span></span>
<span class="line"><span>Ctrl+B, (           Switch to previous session</span></span>
<span class="line"><span>Ctrl+B, )           Switch to next session</span></span>
<span class="line"><span>Ctrl+B, s           List all sessions (interactive)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Windows (like browser tabs)</span></span>
<span class="line"><span>Ctrl+B, c           Create new window</span></span>
<span class="line"><span>Ctrl+B, ,           Rename current window</span></span>
<span class="line"><span>Ctrl+B, n           Next window</span></span>
<span class="line"><span>Ctrl+B, p           Previous window</span></span>
<span class="line"><span>Ctrl+B, 0-9         Switch to window by number</span></span>
<span class="line"><span>Ctrl+B, w           List all windows</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Panes (split screen)</span></span>
<span class="line"><span>Ctrl+B, %           Split vertically (side by side)</span></span>
<span class="line"><span>Ctrl+B, &quot;           Split horizontally (top/bottom)</span></span>
<span class="line"><span>Ctrl+B, Arrow       Move to pane</span></span>
<span class="line"><span>Ctrl+B, z           Zoom/unzoom current pane (fullscreen)</span></span>
<span class="line"><span>Ctrl+B, x           Close current pane</span></span>
<span class="line"><span>Ctrl+B, {           Move pane left</span></span>
<span class="line"><span>Ctrl+B, }           Move pane right</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Scrolling</span></span>
<span class="line"><span>Ctrl+B, [           Enter copy/scroll mode</span></span>
<span class="line"><span>Arrow keys / PgUp   Scroll</span></span>
<span class="line"><span>q                   Exit scroll mode</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><h2 id="custom-tmux-config" tabindex="-1">Custom Tmux Config <a class="header-anchor" href="#custom-tmux-config" aria-label="Permalink to &quot;Custom Tmux Config&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.tmux.conf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change prefix to Ctrl+A (easier to reach)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> C-a</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unbind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> C-b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> C-a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> send-prefix</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable mouse support (click to switch panes, scroll)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mouse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start windows and panes at 1, not 0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> base-index</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setw</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pane-base-index</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Status bar</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status-style</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bg=colour234,fg=colour255</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status-left</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;#[fg=colour82][#S] &#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status-right</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;#[fg=colour82]%H:%M #[fg=colour255]%Y-%m-%d&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Increase history</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history-limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>Apply: <code>tmux source ~/.tmux.conf</code></p>`,11)])])}const d=n(p,[["render",l]]);export{u as __pageData,d as default};
